nav='''<div class="top"><div class="wrap"><span>Private Security Industry Regulatory Authority</span><span>086 10 PSiRA (77472) · info@psira.co.za · Mon-Fri 07:30-16:00</span></div></div><div class="nav"><div class="wrap"><a class="logo" href="index.html"><img src="assets/psira_logo_crop.png"><span>PSiRA</span></a><div class="links"><a href="about.html">About</a><a href="services.html">Services</a><a href="news.html">News & Media</a><a href="documents.html">Documents</a><a href="tenders.html">Tenders</a><a href="careers.html">Careers</a><a href="contact.html">Contact</a></div><div class="actions"><a class="btn" href="login.html">e-PSiRA Login</a><a class="btn brand" href="services.html">Online Services</a></div></div></div>'''
footer='''<div class="footer"><div class="wrap footer-grid"><div><div class="logo"><img src="assets/psira_logo_crop.png"><span>PSiRA</span></div><p>Regulating the private security industry in the public and national interest.</p></div><div><h4>Quick links</h4><p><a>Online registration</a><br><a>Individual verification</a><br><a>Business verification</a><br><a>Accredited training providers</a></p></div><div><h4>Information</h4><p><a>Legislation</a><br><a>Publications</a><br><a>Tenders</a><br><a>Vacancies</a></p></div><div><h4>Contact</h4><p>420 Witch-Hazel Avenue, Eco Glades 2 Office Park, Centurion<br>086 10 PSiRA (77472)</p></div></div><div class="wrap" style="border-top:1px solid #2d3748;margin-top:28px;padding-top:18px;font-size:12px;color:#9ca3af">POPIA · PAIA Manual · Privacy Policy · Terms of Use · Accessibility</div></div>'''
def page(title, body, extra=''):
    return f'<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | PSiRA Concept</title><style>{css}</style></head><body>{extra or nav}{body}{"" if extra else footer}</body></html>'
def subhero(title,desc,k='Public information'):
    return f'<section class="subhero"><div class="wrap"><div class="crumb">Home / {title}</div><div class="kicker">{k}</div><h1>{title}</h1><p class="lead">{desc}</p></div></section>'
# Home
body='''<section class="hero"><div class="wrap hero-grid"><div><span class="eyebrow">Trusted regulation · Digital-first service</span><h1>Safer communities through a stronger security industry.</h1><p>A modern public gateway to PSiRA information, regulation, online services, tenders, careers and digital self-service.</p><div class="hero-actions"><a class="btn brand" href="login.html">Access e-PSiRA</a><a class="btn" href="services.html">Explore services</a></div><div class="statbar"><div class="stat"><b>24/7</b><span>Digital access</span></div><div class="stat"><b>1 portal</b><span>Unified services</span></div><div class="stat"><b>WCAG</b><span>Accessible by design</span></div><div class="stat"><b>Secure</b><span>POPIA-aware</span></div></div></div><div class="panel service-panel"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><div><div class="kicker">Online services</div><h3 style="margin:5px 0">What do you need to do?</h3></div><span class="badge red">e-PSiRA</span></div><div class="service-grid"><div class="service"><div class="icon">ID</div><h4>Individual services</h4><p>Register, verify, renew and manage your profile.</p></div><div class="service"><div class="icon">B</div><h4>Business services</h4><p>Registration, renewals, branches and compliance.</p></div><div class="service"><div class="icon">T</div><h4>Training providers</h4><p>Accreditation, instructors, courses and manuals.</p></div><div class="service"><div class="icon">✓</div><h4>Verification</h4><p>Check individual or business registration status.</p></div></div></div></div></section>
<section class="section white"><div class="wrap"><div class="kicker">Latest from PSiRA</div><h2>News, notices and upcoming events</h2><div class="cards"><div class="card"><span class="badge red">Circular</span><h3>Industry compliance update</h3><p>Current notices and circulars surfaced prominently with clear dates and downloadable supporting documents.</p><div class="meta"><span>24 Aug 2026</span><span>4 min read</span></div></div><div class="card"><span class="badge">News</span><h3>Acting Police Minister visits PSiRA Head Office</h3><p>A media-rich news card with image support, social sharing and related stories.</p><div class="meta"><span>Latest news</span></div></div><div class="card"><span class="badge">Event</span><h3>Stakeholder engagement session</h3><p>Upcoming event detail with date, time, venue or online link and downloadable documents.</p><div class="meta"><span>Centurion</span><span>10:00</span></div></div></div></div></section>
<section class="section"><div class="wrap split"><div><div class="kicker">Key services</div><h2>Find what you need faster.</h2><div class="list"><div class="list-item"><div class="num">01</div><div><b>Registration & renewals</b><div class="small">Individual, business and in-house security business services.</div></div></div><div class="list-item"><div class="num">02</div><div><b>Training & accreditation</b><div class="small">Providers, instructors, programmes and digital manuals.</div></div></div><div class="list-item"><div class="num">03</div><div><b>Enforcement & complaints</b><div class="small">Regulatory information, complaint channels and inspector resources.</div></div></div></div></div><div class="notice"><div class="kicker" style="color:#fda4af">Featured publication</div><h2>Annual Report 2024/25</h2><p>Important publications become easy to discover, preview, filter and download from a structured document library.</p><a class="btn soft" href="documents.html">Open document library</a></div></div></section>
<section class="section white"><div class="wrap"><div class="split"><div><div class="kicker">Opportunities</div><h2>Tenders & vacancies</h2><p class="lead">Current opportunities are separated from closed and archived items, with deadlines, submission details and downloadable notices visible at a glance.</p></div><div class="cards" style="grid-template-columns:1fr 1fr;margin:0"><div class="card"><span class="badge red">Tender</span><h3>Current bid opportunities</h3><p>Closing dates, briefing details and tender documents.</p></div><div class="card"><span class="badge">Vacancy</span><h3>Join PSiRA</h3><p>Current posts, internships and application instructions.</p></div></div></div></div></section>'''
(root/'index.html').write_text(page('Home',body))
