login='''<div class="login-shell"><div class="login-art"><div class="logo"><img src="assets/psira_logo_crop.png"><span>e-PSiRA</span></div><div><span class="eyebrow" style="background:#ffffff18;color:#fff;border-color:#ffffff30">Secure digital services</span><h1>Your PSiRA services, in one place.</h1><p style="color:#d1d5db;max-width:520px">Register, renew, verify, manage business services and track applications through a secure, mobile-friendly portal.</p></div><div class="small" style="color:#9ca3af">Protected by modern authentication, OTP and role-based access controls.</div></div><div class="login-form"><div class="form-card"><div class="kicker">Welcome back</div><h2 style="font-size:34px;margin:8px 0">Log in to e-PSiRA</h2><p class="lead" style="font-size:14px">Use your existing profile credentials.</p><div class="field"><label>Username</label><input placeholder="Enter username"></div><div class="field"><label>Password</label><input placeholder="••••••••" type="password"></div><div style="display:flex;justify-content:space-between;margin:12px 0;font-size:13px"><label><input type="checkbox"> Remember me</label><a style="color:#9f1239;font-weight:700">Forgot password?</a></div><a class="btn brand" href="dashboard.html" style="width:100%">Log in securely</a><div style="text-align:center;margin:22px 0;color:#98a2b3;font-size:12px">or</div><div class="cards" style="grid-template-columns:1fr 1fr;margin:0"><a class="card" style="padding:14px;text-align:center"><b>Claim profile</b></a><a class="card" style="padding:14px;text-align:center"><b>Register now</b></a></div><p class="small" style="margin-top:20px">Personal information is processed lawfully and protected using appropriate technical and organisational safeguards.</p></div></div></div>'''
(root/'login.html').write_text(page('e-PSiRA Login',login,extra=''))
