(root/'login.html').write_text(f'<!doctype html><html><head><meta charset="utf-8"><style>{css}</style></head><body>{login}</body></html>')
# dashboard and cms
side='''<aside class="side"><div class="logo" style="margin-bottom:28px"><img src="assets/psira_logo_crop.png"><span>e-PSiRA</span></div><div class="navitem active">Overview</div><div class="navitem">My applications</div><div class="navitem">Registrations</div><div class="navitem">Certificates</div><div class="navitem">Payments</div><div class="navitem">Documents</div><div class="navitem">Messages</div><div class="navitem">Profile & security</div><div class="navitem" style="margin-top:30px">Help & support</div></aside>'''
dash=f'''<div class="dash">{side}<main class="main"><div class="dashhead"><div><div class="kicker">e-PSiRA dashboard</div><h1 style="margin:6px 0">Good morning, Thabo</h1><p class="small">Here is your registration and compliance overview.</p></div><div class="actions"><a class="btn">Notifications 3</a><a class="btn brand">Start new application</a></div></div><div class="board"><div class="card span4"><div class="small">Registration status</div><h2>Active</h2><span class="badge" style="background:#ecfdf3;color:#067647">Verified</span></div><div class="card span4"><div class="small">Next renewal</div><h2>18 Nov 2026</h2><p class="small">75 days remaining</p></div><div class="card span4"><div class="small">Outstanding actions</div><h2>2</h2><p class="small">1 document · 1 payment</p></div><div class="card span8"><div style="display:flex;justify-content:space-between"><h3>Application progress</h3><span class="badge red">REF PS-2026-01482</span></div><p class="small">Security Officer Renewal</p><div class="progress"><span style="width:68%"></span></div><div class="meta"><span>Submitted ✓</span><span>Verification ✓</span><span>Payment pending</span><span>Decision</span></div></div><div class="card span4"><h3>Quick actions</h3><div class="list"><div class="list-item"><div class="num">✓</div><div><b>Verify status</b></div></div><div class="list-item"><div class="num">↓</div><div><b>Download certificate</b></div></div><div class="list-item"><div class="num">R</div><div><b>Make payment</b></div></div></div></div><div class="card span12"><h3>Recent activity</h3><table class="table"><tr><th>Date</th><th>Activity</th><th>Status</th><th>Reference</th></tr><tr><td>02 Sep 2026</td><td>Renewal application updated</td><td><span class="badge">In review</span></td><td>PS-2026-01482</td></tr><tr><td>29 Aug 2026</td><td>Supporting document uploaded</td><td><span class="badge">Received</span></td><td>DOC-8832</td></tr></table></div></div></main></div>'''
(root/'dashboard.html').write_text(f'<!doctype html><html><head><meta charset="utf-8"><style>{css}</style></head><body>{dash}</body></html>')
cms_side='''<aside class="side"><div class="logo" style="margin-bottom:28px"><img src="assets/psira_logo_crop.png"><span>PSiRA CMS</span></div><div class="navitem active">Dashboard</div><div class="navitem">Pages</div><div class="navitem">News & media</div><div class="navitem">Events</div><div class="navitem">Documents</div><div class="navitem">Tenders</div><div class="navitem">Vacancies</div><div class="navitem">Forms & enquiries</div><div class="navitem">Users & roles</div><div class="navitem">Audit log</div><div class="navitem">Site settings</div></aside>'''
